export function jlrSvg(lang, kind) {
  if (typeof lang !== 'string' || !['fr', 'en'].includes(lang) || typeof kind !== 'string' || !JLR_KINDS.includes(kind)) {
    throw new TypeError('Invalid JLR figure variant');
  }
  return FIGURES[`${kind}-${lang}`];
}

const SOURCE_ANCHORS = Object.freeze({
  "https://media.production.jlrms.com/2026-07-16/pdf/1b96461d-5ffd-4d1a-af0b-5cd8ebe3b7a0/JLR_AnnualReport_FY26.pdf?VersionId=xikZbhVtRFrOPHul.rwdanl8IgGizAHD": "#source-06",
  "https://media.jlr.com/corporate/news/2025/09/statement-cyber-incident": "#source-02",
  "https://media.production.jlrms.com/2025-08-08/pdf/7304004d-ecd5-4d31-89dd-bbdca11a63df/FY26%20Q1%20Narrative%20Reporting.pdf?VersionId=nnH3TVkvrTsK9oocQOChXWMu7kZXyNIe": "#source-11",
  "https://media.production.jlrms.com/2025-11-14/pdf/5e39d1a1-ba79-4bf7-8aea-be456b7c5cf5/FY26%20Q2%20Interim%20Financial%20Statements.pdf?VersionId=.qldkmajqLW.Suulo8MYoxfuxwSG7MPC": "#source-12"
});
export const JLR_REQUIRED_SOURCES = Object.freeze({
  circuit: Object.freeze(['01', '04', '05', '06']),
  recovery: Object.freeze(['01', '02', '04', '05', '09', '14']),
  quarters: Object.freeze(['06', '11', '12', '13', '14']),
  inventory: Object.freeze(['12', '13']),
});

export function jlrSourceAnchor(url) {
  if (typeof url !== 'string' || !Object.hasOwn(SOURCE_ANCHORS, url)) throw new TypeError('Unknown JLR SVG source URL');
  return SOURCE_ANCHORS[url];
}

export function jlrReferences(kind, sources) {
  if (typeof kind !== 'string' || !JLR_KINDS.includes(kind) || typeof sources !== 'string') throw new TypeError('Invalid JLR source references');
  const references = sources.trim() ? sources.trim().split(/\s+/u) : [];
  const required = JLR_REQUIRED_SOURCES[kind];
  const allowed = kind === 'recovery' ? [...required, '10'] : required;
  if (references.length === 0 || new Set(references).size !== references.length || references.some(id => !allowed.includes(id)) || required.some(id => !references.includes(id))) {
    throw new TypeError('Incomplete or invalid JLR source references');
  }
  return Object.freeze(references);
}

export function jlrInlineSvg(lang, kind) {
  // The only raw HTML is the reviewed static SVG above. Bibliography anchors stay local.
  return jlrSvg(lang, kind)
    .replace(/^<svg /u, '<svg style="width:100%;height:auto" ')
    .replace(/ href="([^"]+)"/gu, (_attribute, url) => ` href="${jlrSourceAnchor(url)}"`);
}
